INSERT INTO "posts" ("id", "title", "slug", "excerpt", "content", "cover_image", "category", "tags", "author_id", "published", "featured", "read_time", "view_count", "like_count", "comment_count", "created_at", "updated_at") VALUES ('f1010001-0000-4000-a000-000000000007', 'Web Security Fundamentals: Hardening Modern Full-Stack Applications Against Attacks', 'web-security-fundamentals-hardening-fullstack-applications', 'A practical guide to mitigating the OWASP Top 10 vulnerabilities: Content Security Policy (CSP), Cross-Site Scripting (XSS), SQL Injection, and secure session management.', '<h1>Web Security Fundamentals: Hardening Modern Full-Stack Applications Against Attacks</h1>
INSERT INTO "posts" ("id", "title", "slug", "excerpt", "content", "cover_image", "category", "tags", "author_id", "published", "featured", "read_time", "view_count", "like_count", "comment_count", "created_at", "updated_at") VALUES ('e7211aee-a200-426c-bbad-0bb95f6bf858', 'The Girl Who Borrowed Five Minutes From Tomorrow | Magical Bedtime Story for Kids', 'the-girl-who-borrowed-five-minutes-from-tomorrow-magical-bedtime-story-for-kids-nsst', 'The Girl Who Borrowed Five Minutes From Tomorrow is a magical bedtime story for kids about Maya, a curious girl who discovers that borrowing five minutes from the future comes with a price. Her journey takes her into a mysterious world of clocks, lost time, and an unexpected friendship.
